package tray

import (
	_ "embed"
	"runtime"
)

// The icons are generated by `go run ./tools/genicon` and committed, so a
// plain `go build` needs nothing installed.
//
//go:embed assets/icon_idle.ico
var iconIdleICO []byte

//go:embed assets/icon_live.ico
var iconLiveICO []byte

//go:embed assets/icon_idle.png
var iconIdlePNG []byte

//go:embed assets/icon_live.png
var iconLivePNG []byte

// IconIdle returns the bytes of the "not sharing" icon.
func IconIdle() []byte { return iconBytes(iconIdleICO, iconIdlePNG) }

// IconLive returns the bytes of the "sharing" icon.
func IconLive() []byte { return iconBytes(iconLiveICO, iconLivePNG) }

// iconBytes picks the container the current platform understands: Windows wants
// an .ico (fyne.io/systray parses it with a Win32 icon loader) while macOS and
// Linux want a PNG.
func iconBytes(ico, png []byte) []byte {
	if runtime.GOOS == "windows" {
		return ico
	}
	return png
}
